// Read-only, fixture-specific measurements after visual inspection of r5 outputs.
// Never modifies generated files; fixed coordinates are documented observations.
import {createRequire} from 'node:module';import {readFile,writeFile} from 'node:fs/promises';import path from 'node:path';
const require=createRequire(new URL('../../apps/paperbanana-api/package.json',import.meta.url)),sharp=require('sharp'),dir=process.argv[2];
const specs=[{file:'generate-png-1-candidate-0.png',zero:670,top40:367,alphaX:500,betaX:880,scanFrom:390,flowX:300,flowFrom:100,flowTo:330},{file:'refine-png-1-candidate-0.png',zero:1346,top40:735,alphaX:1000,betaX:1760,scanFrom:780,flowX:600,flowFrom:200,flowTo:650}];
const results=[];for(const s of specs){const {data,info}=await sharp(await readFile(path.join(dir,s.file))).flatten({background:'#fff'}).removeAlpha().raw().toBuffer({resolveWithObject:true});const blue=(x,y)=>{const i=(y*info.width+x)*info.channels,[r,g,b]=data.subarray(i,i+3);return b-r>30&&b>120&&r<150};const first=(x,start,end)=>{for(let y=start;y<end;y++)if(Array.from({length:6},(_,i)=>blue(x,y+i)).every(Boolean))return y;throw Error('No contiguous bar pixels at expected position');};const alphaTop=first(s.alphaX,s.scanFrom,s.zero),betaTop=first(s.betaX,s.scanFrom,s.zero),flowTop=first(s.flowX,s.flowFrom,s.flowTo);const alphaHeight=s.zero-alphaTop,betaHeight=s.zero-betaTop;results.push({...s,width:info.width,height:info.height,alphaTop,betaTop,alphaHeight,betaHeight,flowTop,normalizedFlowTop:flowTop/info.height,heightRatio:alphaHeight/betaHeight,expectedRatio:35/12,relativeRatioError:Math.abs(alphaHeight/betaHeight/(35/12)-1),axisLabelInspection:'Visible labels 0,10,20,30,40,40: duplicate 40 makes axis value interpretation invalid.',method:'Manually verified interior sampling positions; six contiguous blue pixels identify top boundaries; 2px/4px approximate boundary tolerance. Ratio is independent of the ambiguous axis. No image edited; not a general chart parser or statistical certificate.'});}
await writeFile(path.join(dir,'independent-png-measurements.json'),JSON.stringify(results,null,2));console.log(JSON.stringify(results,null,2));
